export type uploadResponse200 = {
  data: IngestionResult
  status: 200
}

export type uploadResponse400 = {
  data: IngestionResult
  status: 400
}

export type uploadResponseSuccess = (uploadResponse200) & {
  headers: Headers;
};
export type uploadResponseError = (uploadResponse400) & {
  headers: Headers;
};

export type uploadResponse = (uploadResponseSuccess | uploadResponseError)

export const getUploadUrl = (params?: UploadParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/admin/tools/documents/upload?${stringifiedParams}` : `/admin/tools/documents/upload`
}

/**
 * @summary Upload and ingest a document
 */
export const upload = async (uploadBody?: UploadBody,
    params?: UploadParams, options?: RequestInit): Promise<uploadResponse> => {
    const formData = new FormData();
if(uploadBody?.file !== undefined) {
 formData.append(`file`, uploadBody.file);
 }

  return customFetch<uploadResponse>(getUploadUrl(params),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}



